package com.bank.migration.model;

// The 7 Rs with a relative effort score (0 = none, 10 = highest).
public enum MigrationStrategy {
    RETIRE(0),        // delete it — no migration at all
    RETAIN(0),        // leave it in place for now
    RELOCATE(2),      // move the whole platform, no changes
    REHOST(3),        // lift-and-shift, no code change
    REPURCHASE(4),    // swap to a SaaS product
    REPLATFORM(5),    // small cloud optimizations (e.g. managed DB)
    REFACTOR(9);      // re-architect cloud-native

    private final int effort;
    MigrationStrategy(int effort) { this.effort = effort; }
    public int getEffort() { return effort; }
}
