package com.bank.migration.model;

// An application plus the signals that drive its migration decision.
public class Application {
    private final String name;
    private final boolean used;
    private final boolean blockingDependency;
    private final boolean nearEndOfLife;
    private final boolean operationalBurdenHigh;
    private final boolean highBusinessValue;
    private final boolean needsElasticity;

    public Application(String name, boolean used, boolean blockingDependency,
                       boolean nearEndOfLife, boolean operationalBurdenHigh,
                       boolean highBusinessValue, boolean needsElasticity) {
        this.name = name;
        this.used = used;
        this.blockingDependency = blockingDependency;
        this.nearEndOfLife = nearEndOfLife;
        this.operationalBurdenHigh = operationalBurdenHigh;
        this.highBusinessValue = highBusinessValue;
        this.needsElasticity = needsElasticity;
    }

    public String getName() { return name; }
    public boolean isUsed() { return used; }
    public boolean hasBlockingDependency() { return blockingDependency; }
    public boolean isNearEndOfLife() { return nearEndOfLife; }
    public boolean isOperationalBurdenHigh() { return operationalBurdenHigh; }
    public boolean isHighBusinessValue() { return highBusinessValue; }
    public boolean needsElasticity() { return needsElasticity; }
}
