package com.bank.migration.advise;

import com.bank.migration.model.Application;
import com.bank.migration.model.MigrationStrategy;
import java.util.logging.Logger;

// Recommends the right R from the application's assessment signals.
public class MigrationAdvisor {
    private static final Logger log = Logger.getLogger(MigrationAdvisor.class.getName());

    public MigrationStrategy recommend(Application app) {
        MigrationStrategy choice;

        if (!app.isUsed()) {
            // Redundant/unused → cheapest migration is no migration.
            choice = MigrationStrategy.RETIRE;
        } else if (app.hasBlockingDependency() || app.isNearEndOfLife()) {
            // Cannot or should not move yet.
            choice = MigrationStrategy.RETAIN;
        } else if (app.isHighBusinessValue() && app.needsElasticity()) {
            // Strategic + needs scale → invest in cloud-native.
            choice = MigrationStrategy.REFACTOR;
        } else if (app.isOperationalBurdenHigh()) {
            // Keep the app, hand off ops → managed service.
            choice = MigrationStrategy.REPLATFORM;
        } else {
            // Default fast path: exit the data center with no code change.
            choice = MigrationStrategy.REHOST;
        }

        final MigrationStrategy c = choice;
        log.info(() -> "[" + app.getName() + "] → " + c + " (effort " + c.getEffort() + ")");
        return choice;
    }
}
