package com.bank.migration.plan;

import com.bank.migration.model.Application;
import com.bank.migration.model.MigrationStrategy;
import com.bank.migration.advise.MigrationAdvisor;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Runs the advisor across the whole portfolio and totals the effort.
public class PortfolioPlanner {
    private static final Logger log = Logger.getLogger(PortfolioPlanner.class.getName());
    private final MigrationAdvisor advisor;

    public PortfolioPlanner(MigrationAdvisor advisor) {
        this.advisor = advisor;
    }

    public Map<String, MigrationStrategy> plan(List<Application> portfolio) {
        Map<String, MigrationStrategy> plan = new LinkedHashMap<>();
        int totalEffort = 0;

        for (Application app : portfolio) {
            MigrationStrategy r = advisor.recommend(app);
            plan.put(app.getName(), r);
            totalEffort += r.getEffort();
        }

        final int effort = totalEffort;
        log.info(() -> "Portfolio plan complete — total relative effort = " + effort);
        return plan;
    }
}
