package com.bank.migration;

import com.bank.migration.advise.MigrationAdvisor;
import com.bank.migration.model.Application;
import com.bank.migration.plan.PortfolioPlanner;
import java.util.List;
import java.util.logging.Logger;

// Runnable demo: four applications matching the four banking problems.
public class MigrationApplication {
    private static final Logger log = Logger.getLogger(MigrationApplication.class.getName());

    public static void main(String[] args) {
        // Problem 1: unused expense tool → RETIRE.
        Application expenseTool = new Application("expense-tool",
                false, false, false, false, false, false);

        // Problem 2: settlement adapter, blocking dep + end-of-life → RETAIN.
        Application settlement = new Application("settlement-adapter",
                true, true, true, false, false, false);

        // Problem 3: customer-accounts DB, high ops burden → REPLATFORM.
        Application accountsDb = new Application("customer-accounts-db",
                true, false, false, true, false, false);

        // Problem 4: payments monolith, high value + needs scale → REFACTOR.
        Application payments = new Application("payments-monolith",
                true, false, false, false, true, true);

        MigrationAdvisor advisor = new MigrationAdvisor();
        PortfolioPlanner planner = new PortfolioPlanner(advisor);

        log.info("=== National Bank of India — cloud migration assessment ===");
        planner.plan(List.of(expenseTool, settlement, accountsDb, payments));
    }
}
